#!/usr/bin/env node
/**
 * Gate: the Companion RPC surface must be SEMANTICALLY equivalent to the Tauri
 * commands it fronts — not merely name-equivalent.
 *
 * ## Why the existing gates cannot catch this
 *
 * Three gates already compare command lists:
 *   - `audit:command-parity`            invoke("x") ⟷ generate_handler!
 *   - `audit:companion-command-manifest` manifest ⟷ generate_handler! ⟷ KNOWN_COMMANDS
 *   - `companion-api:check`              committed OpenAPI bytes ⟷ regenerated bytes
 *
 * Every one of them compares NAME SETS. The manifest gate's only schema check
 * is `if (!command.inputSchema)` — a truthiness test that `RpcArgs` satisfies.
 * So a dispatch arm may accept half its command's arguments, drop the event
 * channel the result arrives on, and flatten a typed error to a string, and
 * the whole gate matrix stays green.
 *
 * That is not hypothetical. `claude_set_provider_env` silently dropped
 * `custom_headers` (the `ANTHROPIC_CUSTOM_HEADER_*` forwarding that gates 1M
 * context behind `anthropic-beta`); `claude_set_mode` hardcodes `command_id`
 * to `None`, so a remote caller structurally cannot correlate the sidecar ack;
 * `mcp_oauth_authenticate` drops `helper_path` and calls a different function.
 *
 * ## Why the schema artifacts cannot catch it either
 *
 * `scripts/build/gen-companion-api.mjs` never opens `src-tauri/src/lib.rs` and
 * never parses a `#[tauri::command]` signature. Request schemas are 429/493
 * hand-written; the other 64 come from `schemaFromArm()`, a regex over the
 * dispatch arm — i.e. derived from the TRUNCATED side of the boundary. A
 * schema generated from a lossy arm documents the loss as the contract. It is
 * a fixed point of the bug, not a check on it.
 *
 * And these schemas are not documentation: `remote_execution.rs` validates
 * every request against the embedded catalog, enforcement on by default. So a
 * truncation is simultaneously invisible to CI and a hard 422 against the
 * correct, fuller payload.
 *
 * This gate is the missing artifact: it reads the `#[tauri::command]`
 * signatures themselves and holds the RPC side to them.
 *
 * ## Ratchet, not a cliff
 *
 * Same contract as `check-colocated-tests.mjs` and
 * `check-unreachable-components.mjs`: pre-existing findings live in
 * `rpc-semantic-parity-baseline.json` and THE LIST MAY ONLY SHRINK.
 *
 * Usage:
 *   pnpm audit:rpc-semantic-parity                     # check
 *   pnpm audit:rpc-semantic-parity -- --report         # full findings, ungated
 *   pnpm audit:rpc-semantic-parity -- --write-baseline # after paying debt down
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { execFileSync } from "node:child_process"
import { fileURLToPath } from "node:url"
import { dirname, join } from "node:path"
import { parseRegisteredCommands } from "./lib/generate-handler.mjs"

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..")
export const BASELINE_FILE = join(
  REPO_ROOT,
  "scripts",
  "gates",
  "rpc-semantic-parity-baseline.json"
)

/** Rust trees that can define a `#[tauri::command]`. */
export const COMMAND_ROOTS = ["src-tauri/src/", "crates/"]

/** Renderer roots that emit Tauri events. Scanned only for channel names. */
export const EMIT_SOURCE_ROOTS = ["lib/", "components/", "hooks/", "stores/", "plugins/"]

/**
 * Parameter types Tauri injects rather than deserializing from the caller's
 * JSON. They are not part of the wire contract, so their absence on the RPC
 * side is never a truncation.
 *
 * `Channel<T>` is injected too, but it is the opposite of harmless: it marks a
 * STREAMING command, and the RPC plane has no channel concept. Those are
 * reported separately (`channel-command`) rather than silently dropped.
 */
const INJECTED_TYPE =
  /^(?:tauri::)?(?:AppHandle|Window|WebviewWindow|State|Runtime|Manager|Emitter|Listener)\b/

const CHANNEL_TYPE = /^(?:tauri::)?(?:ipc::)?Channel\s*</

/**
 * Parameters a dispatch arm deliberately does NOT accept from the wire, keyed
 * `<command>.<param>`, with the reason.
 *
 * Working Rule 7: intentional dormancy must be written down, not inferred from
 * absence. Every entry here is a parameter that names a local executable or
 * script; honouring it from a remote caller would let a paired device pick
 * which binary the host runs, which is remote code execution with extra steps.
 * The host chooses these itself, and the arm is correct to ignore them.
 *
 * A stale row — an exemption for a parameter the command no longer has — is a
 * gate failure, so this list cannot quietly outlive its subject.
 */
export const HOST_CHOSEN_PARAMS = {
  "mcp_oauth_authenticate.helper_path":
    "path to an OAuth helper binary that run_helper() executes (src-tauri/src/mcp_oauth.rs:166); the headless path picks it host-side",
  "mcp_oauth_refresh.helper_path":
    "same helper binary as mcp_oauth_authenticate, executed by run_helper()",
  "mcp_server_start.sidecar_path":
    "filesystem path to the Node sidecar script the host spawns (crates/cognia-mcp-server/src/commands.rs:20)",
  "mcp_server_restart.sidecar_path": "same sidecar script path as mcp_server_start",
  "plugin_load_vscode.sidecar_script":
    "path to the VS Code extension host script the plugin runtime launches",
  "plugin_load_vscode.node_binary":
    "path to the Node binary used to launch the extension host sidecar",
}

/**
 * Channel-name prefixes that are host-local by design and must never be
 * remotely deliverable, so their absence from `EVENT_CHANNELS` is the correct
 * answer rather than a gap.
 *
 * These are window-to-window plumbing: they address a specific desktop surface
 * (the tray popover, the pet sprite, the selection toolbar) and mean nothing to
 * a phone. Several also carry material that should never leave the machine —
 * `selection://stage` embeds the user's selected text from whatever app they
 * were in, and `record:event` carries keystrokes plus OCR of the screen.
 */
export const HOST_LOCAL_CHANNELS = [
  "app://",
  "cli://",
  "cli-bridge:",
  "cognia://",
  "deep-link://",
  "download_cognia_cli",
  "fleet://island-",
  "log://",
  "menu://",
  "ollama-pull-progress",
  "pet://",
  "pet-popup://",
  "plugin-fs-watch:",
  "plugin-hot-reload",
  "record:",
  "recorder:",
  // Automation worker crash/restart diagnostics. They carry a panic message
  // and a retry count about the host's own automation worker process, have no
  // listener anywhere, and describe a fault in the machine rather than a
  // result a remote caller is waiting on.
  "automation:worker-",
  "security://",
  "selection://",
  "shortcut://",
  "tray://",
  "tray-panel://",
  "vscode://",
  // Renderer-answered request channels for the desktop data bridge. The remote
  // side reaches this data through RPC, never by observing the host's own
  // request stream.
  "companion://desktop-write-request",
  "companion://message-",
  "companion://session-",
  "companion://sync-pull-request",
  "companion://transcript-capabilities-request",
  "companion://needs-input",
  "claude-settings-changed",
]

/**
 * Streaming commands (`Channel<T>`) deliberately kept off the RPC plane,
 * keyed by command name, with the replacement that serves the same need.
 *
 * The RPC plane has no channel concept, so a streaming command cannot simply
 * be allowlisted — it needs a different transport. Each of these HAS one, or
 * has a recorded decision that it needs a design first. Without this table the
 * gate cannot tell "replaced by a better transport" from "nobody noticed", and
 * those are the two states this whole audit exists to separate.
 *
 * A stale row fails the gate, so the table cannot outlive its subject.
 */
export const STREAM_COMMAND_REPLACEMENTS = {
  terminal_spawn:
    "replaced by the GET /ws/terminal binary protocol (src-tauri/src/companion_api/ws_terminal.rs): a paired client redeems a device-bound socket ticket and the PTY stays owned by `cognia-server desktop-host`, so it survives this process disconnecting — which a Channel<T> over IPC cannot do",
  terminal_reattach:
    "same /ws/terminal route; reattaching is opening the socket against an existing session id, so it needs no separate command",
  ssh_terminal_spawn:
    "same /ws/terminal route, which carries SSH-backed sessions on the identical canonical frame protocol",
}

/**
 * Dispatch arms that require `host.headless()` and are NOT in
 * `SERVICE_ONLY_COMMANDS`, where answering 503 on a desktop-hosted companion
 * server is the correct behaviour rather than a wiring mistake.
 *
 * The distinction matters: a device-reachable arm that 503s on desktop is
 * usually a bug (the audit found 17 of them), but it is the right answer when
 * the capability genuinely belongs to the remote host and not to the paired
 * desktop.
 */
export const HEADLESS_OWNED_ARMS = {
  // Empty, and that is the finding this table was built to force.
  //
  // It used to hold the four `codeserver_*` lifecycle arms on the claim that
  // "a desktop-hosted companion server has no instance to ensure". That claim
  // was read off `HeadlessServices.code_server`'s docstring, which describes
  // the REMOTE host's pinned instance and is still true about that field. It
  // was never true about the desktop: `src-tauri/src/lib.rs` manages a
  // `CodeServerState`, `src-tauri/src/codeserver/commands.rs` exposes the same
  // four verbs as Tauri commands, and `lib/codeserver/client.ts` drives them.
  // So the arms were refusing a request a desktop host was perfectly able to
  // serve, for four commands the manifest advertises to every paired phone as
  // `target: execution` over http/websocket/webrtc.
  //
  // They now branch through `DispatchHost::ide_{ensure,status,stop,stop_all}`,
  // the same seam `ide_read_user_settings` and `ide_open_file` already used.
  // Keep the table: the next arm that genuinely belongs to the remote host
  // needs a row here, and a row that outlives its subject fails the gate.
}

/** Findings that are gated. Anything else is report-only. */
export const GATED_KINDS = new Set([
  "stale-host-chosen-exemption",
  "deadlocked-contract",
  "missing-params",
  "schema-missing-params",
  "arm-not-allowlisted",
  "known-command-without-arm",
  "unregistered-command",
  "unsubstantiated-coverage-claim",
  "stale-stream-exemption",
  "stale-headless-owned-exemption",
  // Gated now that it is at zero. The audit found 17 of these: arms the
  // manifest advertises to every paired device over http/websocket/webrtc,
  // which then answer 503 `headless_unsupported` on a desktop host, whose
  // message tells the operator to use the desktop app they are already using.
  // Every one has since been routed through `DispatchHost`, and
  // `HEADLESS_OWNED_ARMS` is empty. Report-only was the right setting while
  // there was a backlog to burn down; leaving it report-only after the burndown
  // is how the class comes back, one arm at a time, with nothing failing.
  "desktop-dead",
])

// ---------------------------------------------------------------------------
// Rust source parsing
// ---------------------------------------------------------------------------

/**
 * Strip `//` line comments and block comments. Required, not cosmetic:
 * parameter lists in this repo carry explanatory comments between params
 * (see `claude_set_provider_env`), and a `)` inside one would truncate the
 * balanced-paren scan.
 *
 * String literals are preserved so `"//"` inside one is not eaten.
 * @param {string} src
 * @returns {string}
 */
export function stripRustComments(src) {
  let out = ""
  let i = 0
  let inStr = false
  let inChar = false
  while (i < src.length) {
    const ch = src[i]
    const next = src[i + 1]
    if (inStr) {
      out += ch
      if (ch === "\\") {
        out += next ?? ""
        i += 2
        continue
      }
      if (ch === '"') inStr = false
      i += 1
      continue
    }
    if (inChar) {
      out += ch
      if (ch === "\\") {
        out += next ?? ""
        i += 2
        continue
      }
      if (ch === "'") inChar = false
      i += 1
      continue
    }
    if (ch === '"') {
      inStr = true
      out += ch
      i += 1
      continue
    }
    if (ch === "/" && next === "/") {
      while (i < src.length && src[i] !== "\n") i += 1
      continue
    }
    if (ch === "/" && next === "*") {
      i += 2
      let depth = 1
      while (i < src.length && depth > 0) {
        if (src[i] === "/" && src[i + 1] === "*") {
          depth += 1
          i += 2
        } else if (src[i] === "*" && src[i + 1] === "/") {
          depth -= 1
          i += 2
        } else {
          if (src[i] === "\n") out += "\n"
          i += 1
        }
      }
      continue
    }
    out += ch
    i += 1
  }
  return out
}

/**
 * Text between `open` at `start` and its matching `close`. Returns null when
 * unbalanced. Pure.
 * @param {string} src
 * @param {number} start index OF the opening delimiter
 * @param {string} open
 * @param {string} close
 * @returns {{ text: string, end: number } | null}
 */
export function extractBalanced(src, start, open, close) {
  if (src[start] !== open) return null
  let depth = 0
  for (let i = start; i < src.length; i += 1) {
    if (src[i] === open) depth += 1
    else if (src[i] === close) {
      depth -= 1
      if (depth === 0) return { text: src.slice(start + 1, i), end: i }
    }
  }
  return null
}

/**
 * Split a Rust parameter list on top-level commas — generics, tuples and
 * closures nest, so a naive `split(",")` shreds `State<'_, ApiKeyState>`.
 * @param {string} params
 * @returns {string[]}
 */
export function splitParams(params) {
  const out = []
  let depth = 0
  let current = ""
  for (const ch of params) {
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth += 1
    else if (ch === ">" || ch === ")" || ch === "]" || ch === "}") depth -= 1
    if (ch === "," && depth === 0) {
      out.push(current.trim())
      current = ""
      continue
    }
    current += ch
  }
  if (current.trim()) out.push(current.trim())
  return out.filter(Boolean)
}

/** @param {string} type @returns {boolean} */
export function isInjectedParam(type) {
  return INJECTED_TYPE.test(type.trim().replace(/^&/, ""))
}

/** @param {string} type @returns {boolean} */
export function isChannelParam(type) {
  return CHANNEL_TYPE.test(type.trim().replace(/^&/, ""))
}

/**
 * Normalize a field name for cross-side comparison.
 *
 * The two sides genuinely disagree on casing and it is not a defect: Tauri
 * deserializes `api_key` from the JS `apiKey`, while the RPC arms read raw
 * JSON with `required(&args, "…")` and pick their own spelling — some
 * snake_case (`claude_set_provider_env`), some camelCase (`git_clone`).
 * Comparing on a case/underscore-insensitive key is the only way to ask the
 * question that matters: is the ARGUMENT present at all?
 *
 * @param {string} name
 * @returns {string}
 */
export function normalizeField(name) {
  return name.replace(/[_-]/g, "").toLowerCase()
}

/**
 * Every `#[tauri::command]` in one file, with its real (non-injected) wire
 * parameters. Pure.
 *
 * @param {string} rawSource
 * @param {string} file repo-relative path, for reporting
 * @returns {Array<{name: string, file: string, line: number, params: Array<{name: string, type: string}>, channelParams: string[], returnType: string}>}
 */
export function parseTauriCommands(rawSource, file) {
  const source = stripRustComments(rawSource)
  const out = []
  const attrRe = /#\[tauri::command[^\]]*\]/g
  let attr
  while ((attr = attrRe.exec(source)) !== null) {
    const after = source.slice(attr.index + attr[0].length)
    // Skip any further attributes/whitespace between the marker and the fn.
    const fnMatch = after.match(
      /^(?:\s*#\[[^\]]*\])*\s*(?:pub(?:\s*\([^)]*\))?\s+)?(?:async\s+)?fn\s+([A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*\(/
    )
    if (!fnMatch) continue
    const name = fnMatch[1]
    const parenIndex = attr.index + attr[0].length + fnMatch[0].length - 1
    const parenBlock = extractBalanced(source, parenIndex, "(", ")")
    if (!parenBlock) continue

    const params = []
    const channelParams = []
    for (const raw of splitParams(parenBlock.text)) {
      const m = raw.match(/^(?:mut\s+)?([A-Za-z_]\w*)\s*:\s*([\s\S]+)$/)
      if (!m) continue // `&self`, `_`, destructuring — not a wire param
      const [, paramName, paramType] = m
      if (isChannelParam(paramType)) {
        channelParams.push(paramName)
        continue
      }
      if (isInjectedParam(paramType)) continue
      params.push({ name: paramName, type: paramType.trim() })
    }

    const tail = source.slice(parenBlock.end + 1, parenBlock.end + 400)
    const retMatch = tail.match(/^\s*->\s*([^{]+)\{/)
    out.push({
      name,
      file,
      line: source.slice(0, attr.index).split("\n").length,
      params,
      channelParams,
      returnType: retMatch ? retMatch[1].trim() : "()",
    })
  }
  return out
}

// ---------------------------------------------------------------------------
// RPC dispatch-arm parsing
// ---------------------------------------------------------------------------

/**
 * The arms of a `match name { … }` inside a `dispatch(` function.
 *
 * Anchored on the dispatch fn because `source_control.rs` also matches on
 * `name` inside `prepare_remote_args` — grabbing that one would attribute the
 * wrong body to every git command. Same eight-space rustfmt seam that
 * `gen-companion-api.mjs:extractCommandArgumentSchemas` relies on.
 *
 * The name is matched as `dispatch` or the one named exception, `dispatch_sftp`.
 * It is an explicit alternative and not `dispatch\w*` on purpose: the tree also
 * holds `dispatch_bridge`, `dispatch_dify`, `dispatch_browser_rpc` and
 * `dispatch_canonical`, and since `search` takes the FIRST match, a wildcard
 * would let any of them anchor the scan and donate its arms to commands it does
 * not serve. Most families put
 * their arms behind `pub(super) async fn dispatch(`; SFTP delegates: its
 * arms live in `sftp_service.rs` as `pub async fn dispatch_sftp(`, because the
 * desktop's own `#[tauri::command]` wrappers share that function, so it is
 * named for what it does rather than for the RPC table it happens to serve.
 * Requiring the bare name made all 14 SFTP commands look arm-less, and the
 * gate reported 14 runtime 404s that did not exist — which in turn buried the
 * 18 findings in the same run that were real. `gen-companion-api.mjs` already
 * carries the same carve-out; this is the parity gate catching up to it.
 *
 * @param {string} rawSource
 * @param {string} file
 * @returns {Array<{names: string[], body: string, file: string}>}
 */
export function extractDispatchArms(rawSource, file) {
  const source = stripRustComments(rawSource)
  const dispatchStart = source.search(
    /(?:pub(?:\s*\([^)]*\))?\s+)?async\s+fn\s+dispatch(?:_sftp)?\s*(?:<[^>]*>)?\s*\(/
  )
  if (dispatchStart < 0) return []
  const matchStart = source.indexOf("match name {", dispatchStart)
  if (matchStart < 0) return []

  const lines = source.slice(matchStart).split(/\r?\n/)
  const arms = []
  let current = null

  const finish = () => {
    if (current) arms.push({ names: current.names, body: current.body.join("\n"), file })
    current = null
  }

  for (const line of lines.slice(1)) {
    const isArmStart = /^ {8}"[a-z][a-z0-9_]*"/.test(line)
    const isContinuation = /^ {8}\| "[a-z][a-z0-9_]*"/.test(line)
    if (/^ {8}_\s*=>/.test(line)) {
      finish()
      break
    }
    if (isArmStart && (!current || current.hasArrow)) {
      finish()
      current = { names: armNamesOnLine(line), hasArrow: line.includes("=>"), body: [line] }
      continue
    }
    if (current && !current.hasArrow) {
      if (isArmStart || isContinuation) current.names.push(...armNamesOnLine(line))
      current.hasArrow ||= line.includes("=>")
      current.body.push(line)
      continue
    }
    if (current) current.body.push(line)
  }
  finish()
  return arms
}

/**
 * Command names in an arm's pattern position on one line.
 *
 * Or-patterns come in both spellings and BOTH must be read, or the second name
 * of `"secret_store_get" | "keyring_secret_get" => {` looks arm-less and the
 * gate reports a runtime 404 that does not exist. Only the text before `=>` is
 * the pattern; string literals in the arm body are not names.
 *
 * @param {string} line
 * @returns {string[]}
 */
export function armNamesOnLine(line) {
  const arrow = line.indexOf("=>")
  const pattern = arrow >= 0 ? line.slice(0, arrow) : line
  return [...pattern.matchAll(/"([a-z][a-z0-9_]*)"/g)].map((m) => m[1])
}

/**
 * Fields the arm hard-REQUIRES, each as `[field, alias]`.
 *
 * Distinct from `armReadFields` on purpose. An optional field the schema omits
 * is a capability gap; a *required* field the schema forbids is a deadlock —
 * the command cannot be called at all. Only `required*` helpers produce the
 * latter, so this deliberately ignores `optional*` and raw `args.get`.
 *
 * @param {string} body
 * @returns {Array<[string, string | undefined]>}
 */
export function armRequiredFields(body) {
  const re =
    /\brequired(?:_aliased)?\s*(?:::<[^>]*>)?\s*\(\s*&args\s*,\s*"([^"]+)"(?:\s*,\s*"([^"]+)")?/g
  return [...body.matchAll(re)].map((m) => [m[1], m[2]])
}

/**
 * Does the arm hand the ENTIRE args object onward rather than destructuring it?
 *
 * Two shapes, both faithful by construction:
 *   - `serde_json::from_value(args)` into the command's own struct
 *     (`automation_consent_respond` / `ConsentRespondArgs`)
 *   - forwarding the blob to a downstream dispatcher, e.g.
 *     `dispatch_host_rpc("jobs.read", &args)` for the `background_job_*` family
 *
 * Neither can drop a field, so "never reads `job_id`" would be exactly
 * backwards. The truncation risk for these does not disappear — it moves to
 * the hand-written contract schema, which `schema-missing-params` still
 * checks. That is why this only suppresses the arm-level finding.
 *
 * @param {string} body
 * @returns {boolean}
 */
export function consumesWholeArgs(body) {
  const callRe = /\b([A-Za-z_][\w:]*)\s*(?:::<[^>]*>)?\s*\(([^()]*)\)/g
  for (const [, fn, argList] of body.matchAll(callRe)) {
    // The field readers also receive `&args`, but they name a single field —
    // they are the opposite of a whole-blob hand-off.
    if (/^(?:required|optional)(?:_aliased)?$/.test(fn.split("::").pop() ?? "")) continue
    if (/(?:^|,)\s*&?\s*args(?:\s*\.\s*clone\s*\(\s*\))?\s*(?:,|$)/.test(argList)) return true
  }
  return false
}

/**
 * Field names an arm reads out of the request JSON. Covers the four
 * `required`/`optional`(`_aliased`) helpers plus raw `args.get("…")`, and
 * keeps aliases so an aliased read counts for both spellings.
 *
 * @param {string} body
 * @returns {Set<string>}
 */
export function armReadFields(body) {
  const fields = new Set()
  const helperRe =
    /\b(?:required_aliased|optional_aliased|required|optional)\s*(?:::<[^>]*>)?\s*\(\s*&args\s*,\s*"([^"]+)"(?:\s*,\s*"([^"]+)")?/g
  for (const m of body.matchAll(helperRe)) {
    fields.add(m[1])
    if (m[2]) fields.add(m[2])
  }
  for (const m of body.matchAll(/\bargs\s*\.\s*get\(\s*"([^"]+)"\s*\)/g)) fields.add(m[1])
  for (const m of body.matchAll(/\bargs\s*\.\s*(?:remove|contains_key)\(\s*"([^"]+)"\s*\)/g)) {
    fields.add(m[1])
  }
  return fields
}

/**
 * Does this arm hand the whole `args` blob to another plane instead of
 * destructuring it? The 101-command bridge arm in `data_sync.rs` forwards raw
 * args to the TypeScript brain, so there is no Rust-side argument handling to
 * compare against — those commands are exempted explicitly, never silently.
 *
 * @param {string} body
 * @returns {boolean}
 */
export function isBridgeArm(body) {
  return (
    /desktop_write|desktop_writes_bridge|renderer_request|bridge_request|forward_to_renderer/.test(
      body
    ) && !/\b(?:required|optional)\s*(?:::<[^>]*>)?\s*\(\s*&args/.test(body)
  )
}

/**
 * Arms that require the headless services object. On a desktop-hosted
 * companion server `host.headless()` is `None`, so these answer 503.
 *
 * The message they emit used to be `headless_unsupported` ("requires the
 * desktop app") — the exact opposite of the truth — which is why this is
 * matched on the accessor rather than on any one error name. It now accepts
 * either spelling so the check keeps working through that rename.
 *
 * @param {string} body
 * @returns {boolean}
 */
export function requiresHeadless(body) {
  return (
    /host\s*\.\s*headless\(\)\s*\.\s*ok_or_else/.test(body) &&
    /headless_host_required|headless_unsupported/.test(body)
  )
}

// ---------------------------------------------------------------------------
// Contract artifacts
// ---------------------------------------------------------------------------

/**
 * Property names a JSON Schema declares, or null when the schema is opaque
 * (declares no properties at all — `LegacyResult` and friends).
 * @param {unknown} schema
 * @returns {string[] | null}
 */
export function schemaProperties(schema) {
  if (!schema || typeof schema !== "object") return null
  const props = /** @type {Record<string, unknown>} */ (schema).properties
  if (!props || typeof props !== "object") return null
  return Object.keys(props)
}

/**
 * Every property name a schema can accept, following `anyOf`/`oneOf`/`allOf`.
 *
 * Some commands are modelled as discriminated unions (`twin_profile_update`
 * is a Zod `discriminatedUnion`), so their properties live in the branches and
 * a top-level `properties` lookup finds none — reporting the whole documented
 * request as rejected.
 *
 * @param {unknown} schema
 * @returns {Set<string>}
 */
export function acceptedPropertyNames(schema) {
  const names = new Set()
  const visit = (node, depth) => {
    if (!node || typeof node !== "object" || depth > 6) return
    for (const key of Object.keys(node.properties ?? {})) names.add(key)
    for (const branch of [...(node.anyOf ?? []), ...(node.oneOf ?? []), ...(node.allOf ?? [])]) {
      visit(branch, depth + 1)
    }
  }
  visit(schema, 0)
  return names
}

/**
 * How much of the wire value a response schema actually pins down.
 *
 * The distinction matters because output validation is ENFORCED
 * (`remote_execution.rs:293` and `:362`), so this classification decides what
 * counts as debt worth paying — and paying it wrong converts a working command
 * into a hard error response.
 *
 * - `any`         — `LegacyResult`-shaped, or no schema at all. Every JSON
 *                   value passes, so validation is genuinely a no-op.
 * - `container`   — the root type is pinned (`LegacyRecord` is an object,
 *                   `LegacyList` is an array) but nothing inside it is. A
 *                   wrong root type IS rejected, so this is weak, not vacuous.
 * - `precise`     — constrains the value: a scalar type (`{"type":"null"}`
 *                   admits exactly one value), declared `properties`, or a
 *                   `oneOf`/`anyOf`/`allOf` composition.
 *
 * Written as three grades rather than a boolean because the previous boolean
 * keyed off "declares no `properties`", which put `{"type":"null"}` in the
 * same bucket as `{"type":["object","array","string","number","boolean",
 * "null"]}`. The first is the tightest schema expressible; the second matches
 * everything. That mislabelled 141 commands as unvalidated and inflated the
 * reported debt from 325 to 466.
 *
 * @param {unknown} schema
 * @returns {"any" | "container" | "precise"}
 */
export function responseSchemaPrecision(schema) {
  if (!schema || typeof schema !== "object") return "any"
  const s = /** @type {Record<string, unknown>} */ (schema)
  // A union this wide enumerates every JSON type, which is the same as
  // declaring nothing. Narrower unions (`["object","null"]`) do constrain.
  if (Array.isArray(s.type) && s.type.length > 3) return "any"
  if (schemaProperties(schema) !== null) return "precise"
  if (s.oneOf || s.anyOf || s.allOf) return "precise"
  if (s.enum || s.const !== undefined) return "precise"

  // A union grades as its most permissive member: `["string","null"]` admits
  // two scalars, while `["object","null"]` admits every object there is.
  const types = Array.isArray(s.type) ? s.type : typeof s.type === "string" ? [s.type] : []
  if (types.length === 0) return "any"
  if (types.includes("object")) return "container"
  if (types.includes("array")) {
    // `LegacyList` is an array of `LegacyResult`; a typed `items` is not.
    return responseSchemaPrecision(s.items) === "any" ? "container" : "precise"
  }
  // Scalars admit a bounded set of values — `{"type":"null"}` admits exactly one.
  return "precise"
}

/**
 * An "opaque" schema matches any JSON, so validating against it is a no-op.
 * @param {unknown} schema
 * @returns {boolean}
 */
export function isOpaqueSchema(schema) {
  return responseSchemaPrecision(schema) === "any"
}

/**
 * Every command named in the disposition ledger, across all four groups.
 *
 * Throws on an empty parse rather than returning an empty set. A silently
 * empty allowlist is the exact failure shape this gate exists to catch: it
 * would make every triaged command look untriaged, or — worse, if the check
 * ran the other way — make every untriaged command look accounted for.
 *
 * Note the ledger's `reason` is per-GROUP, not per-command: one sentence
 * covers all 510 `local-only` entries. Presence here proves a command was
 * classified, not that anyone justified it individually.
 *
 * @param {{ groups?: Array<{ disposition: string, commands?: string[] }> }} ledger
 * @returns {Set<string>}
 */
export function parseDispositionNames(ledger) {
  const groups = Array.isArray(ledger?.groups) ? ledger.groups : []
  const names = new Set(groups.flatMap((g) => g.commands ?? []))
  if (names.size === 0) {
    throw new Error(
      "headless-command-dispositions.json parsed to zero commands — the shape changed " +
        "and this gate would silently stop counting triaged commands."
    )
  }
  return names
}

/** Extract a `const NAME: &[&str] = &[ … ];` string array from Rust. */
/**
 * Parse `EVENT_CHANNELS` out of `companion_api/event_channels.rs`.
 *
 * Read from the Rust rather than mirrored into a JSON asset on purpose: the
 * catalog is what the running host enforces, and a mirrored copy is one more
 * thing that can drift from it — which is the failure this whole gate exists
 * to catch.
 *
 * @param {string} source
 * @returns {Map<string, {defaultOn: boolean, tauriForwarded: boolean}>}
 */
export function parseEventChannelCatalog(source) {
  const out = new Map()
  const start = source.indexOf("pub static EVENT_CHANNELS")
  if (start === -1) {
    throw new Error("EVENT_CHANNELS not found in event_channels.rs — parser is stale")
  }
  const body = source.slice(start, source.indexOf("\n];", start))
  const entryRe =
    /pattern:\s*"([^"]+)"\s*,\s*audience:[^,]+,\s*default_on:\s*(true|false)\s*,\s*tauri_forwarded:\s*(true|false)/g
  let match
  while ((match = entryRe.exec(body)) !== null) {
    out.set(match[1], { defaultOn: match[2] === "true", tauriForwarded: match[3] === "true" })
  }
  if (out.size === 0) {
    throw new Error("EVENT_CHANNELS parsed to zero entries — parser is stale")
  }
  return out
}

/**
 * Whether a concrete channel name is covered by a catalog entry, honouring
 * trailing-`*` family patterns exactly as the Rust `matches` does.
 *
 * @param {Map<string, unknown>} catalog
 * @param {string} channel
 */
export function matchesEventCatalog(catalog, channel) {
  if (catalog.has(channel)) return true
  for (const pattern of catalog.keys()) {
    if (pattern.endsWith("*") && channel.startsWith(pattern.slice(0, -1))) return true
  }
  return false
}

/** A channel name: `scheme://rest` or `scheme:rest`. */
const CHANNEL_SHAPE = "[a-z][a-z0-9-]*(?::\\/\\/|:)[a-zA-Z0-9_/.-]*"

/**
 * Strip `#[cfg(test)] mod tests { … }` blocks.
 *
 * Not optional for channel scanning: `event_bus.rs` publishes `test://a`,
 * `a2a/handler.rs` publishes `some://other`, and counting those as production
 * channels would report five fictional gaps and, worse, make a catalogued
 * channel look alive because a fixture happened to name it.
 *
 * @param {string} src
 * @returns {string}
 */
export function stripRustTestModules(src) {
  let out = ""
  let i = 0
  for (;;) {
    const marker = src.indexOf("#[cfg(test)]", i)
    if (marker === -1) return out + src.slice(i)
    const brace = src.indexOf("{", marker)
    if (brace === -1) return out + src.slice(i, marker)
    let depth = 0
    let j = brace
    for (; j < src.length; j += 1) {
      if (src[j] === "{") depth += 1
      else if (src[j] === "}") {
        depth -= 1
        if (depth === 0) break
      }
    }
    out += src.slice(i, marker)
    i = j + 1
  }
}

/**
 * Channel names some production code path emits or publishes.
 *
 * Literal-only by necessity, and that is a real limit: names built with
 * `format!` / template strings (`connectors://onebot/{id}/event`,
 * `menu://{id}`) cannot be resolved statically. Those are covered by the
 * catalog's family patterns rather than by this scan, which is why the
 * uncatalogued check tolerates a miss here but the liveness check below does
 * NOT rely on it.
 *
 * @param {Array<{file: string, source: string}>} files
 * @returns {Map<string, string>} channel → first emit site
 */
export function collectEmittedChannels(files) {
  const out = new Map()
  // `app.emit("x", …)`, `emit_to(label, "x", …)`, `emit_all("x", …)`,
  // `bus.publish("x".to_string(), …)`, `publish_ephemeral_to("x".into(), …)`,
  // and the TS `emit("x", …)` / `emitTo(label, "x", …)`.
  const patterns = [
    new RegExp(
      `\\bemit(?:_all|_to)?\\s*\\(\\s*(?:&?[A-Za-z_][\\w.]*\\s*,\\s*)?"(${CHANNEL_SHAPE})"`,
      "g"
    ),
    new RegExp(`\\bpublish(?:_ephemeral_to)?\\s*\\(\\s*"(${CHANNEL_SHAPE})"`, "g"),
    new RegExp(`\\bemitTo\\s*\\(\\s*[^,]+,\\s*"(${CHANNEL_SHAPE})"`, "g"),
  ]
  for (const { file, source } of files) {
    const clean = file.endsWith(".rs") ? stripRustTestModules(stripRustComments(source)) : source
    for (const re of patterns) {
      re.lastIndex = 0
      let match
      while ((match = re.exec(clean)) !== null) {
        if (!out.has(match[1])) out.set(match[1], file)
      }
    }
  }
  return out
}

/**
 * Every channel name the codebase mentions, plus the static prefixes of every
 * channel-shaped template literal.
 *
 * This is the input to the liveness check, and the distinction from
 * [`collectEmittedChannels`] is the whole point. "Is this channel emitted" is
 * not statically decidable here — `git://status-changed` is emitted through a
 * `const`, `claude://message-added` is assembled as
 * `` `claude://message-${kind}` ``, and half the emitters are in TypeScript
 * while the catalog is in Rust. A check that answered the undecidable question
 * with a literal scan would report ~40 live channels as dead, which is worse
 * than no check.
 *
 * So the question is narrowed to one that IS decidable: does this name appear
 * anywhere at all outside the catalog? A `false` there is unambiguous — the
 * entry is a typo or the constant behind it was renamed. It will not catch a
 * channel that is declared and listened for but never emitted
 * (`companion://device-paired`); nothing static can, and the catalog note
 * records that case in prose instead of pretending otherwise.
 *
 * @param {Array<{file: string, source: string}>} files
 * @returns {{exact: Set<string>, prefixes: string[]}}
 */
export function collectChannelReferences(files) {
  const exact = new Set()
  const prefixes = new Set()
  const literal = new RegExp(`"(${CHANNEL_SHAPE})"`, "g")
  // `` `claude://message-${kind}` `` and Rust's `format!("menu://{id}")`.
  const templateHead = new RegExp('[`"](' + CHANNEL_SHAPE + ")(?:\\$\\{|\\{)", "g")
  for (const { file, source } of files) {
    if (file.endsWith("companion_api/event_channels.rs")) continue
    const clean = file.endsWith(".rs") ? stripRustTestModules(stripRustComments(source)) : source
    literal.lastIndex = 0
    let match
    while ((match = literal.exec(clean)) !== null) exact.add(match[1])
    templateHead.lastIndex = 0
    while ((match = templateHead.exec(clean)) !== null) prefixes.add(match[1])
  }
  return { exact, prefixes: [...prefixes] }
}

export function extractRustStringArray(source, name) {
  const match = source.match(new RegExp(`const ${name}[^=]*= &\\[([\\s\\S]*?)\\n\\];`))
  if (!match) throw new Error(`Could not locate Rust ${name}`)
  return new Set([...match[1].matchAll(/"([a-z0-9_]+)"/g)].map((entry) => entry[1]))
}

// ---------------------------------------------------------------------------
// Analysis
// ---------------------------------------------------------------------------

/**
 * Compare all three sides and produce findings. Pure — every input injected.
 *
 * @param {{
 *   tauriCommands: Map<string, {file: string, line: number, params: Array<{name: string, type: string}>, channelParams: string[], returnType: string}>,
 *   registered: Set<string>,
 *   knownCommands: Set<string>,
 *   serviceOnly: Set<string>,
 *   arms: Map<string, {body: string, file: string}>,
 *   catalog: Map<string, {inputSchema?: unknown, outputSchema?: unknown}>,
 *   manifestNames: Set<string>,
 *   dispositionNames: Set<string>,
 * }} input
 * @returns {Array<{key: string, command: string, kind: string, detail: string}>}
 */
export function analyze(input) {
  const {
    tauriCommands,
    registered,
    knownCommands,
    serviceOnly,
    arms,
    catalog,
    manifestNames,
    dispositionNames,
    browserCommands = new Set(),
    publicSpecSchemas = new Map(),
    devicePlaneOverrides = new Map(),
    eventCatalog = new Map(),
    emittedChannels = new Map(),
    channelReferences = { exact: new Set(), prefixes: [] },
    dispositionGroups = [],
    // Injectable so a test can exercise the staleness rules against its own
    // small inventory; production always passes the full tables.
    hostChosenParams = HOST_CHOSEN_PARAMS,
    streamReplacements = STREAM_COMMAND_REPLACEMENTS,
    headlessOwnedArms = HEADLESS_OWNED_ARMS,
  } = input
  const findings = []
  const add = (command, kind, detail) =>
    findings.push({ key: `${command}:${kind}`, command, kind, detail })

  // --- 0. Deadlocked contracts: unreachable by ANY payload -----------------
  // The arm requires a field the enforced schema forbids. Send it and the
  // contract validator rejects the request 422 before dispatch is reached;
  // omit it and the arm rejects it 400. There is no third option, so the
  // command cannot be called at all. This is strictly worse than a dropped
  // argument and is reported separately from `schema-missing-params`.
  for (const [name, arm] of arms) {
    const entry = catalog.get(name)
    const schema = entry?.inputSchema
    if (!schema || typeof schema !== "object") continue
    if (schema.additionalProperties !== false) continue
    const declared = new Set(Object.keys(schema.properties ?? {}).map(normalizeField))
    const deadlocking = armRequiredFields(arm.body)
      .filter(([field, alias]) => {
        if (declared.has(normalizeField(field))) return false
        return !(alias && declared.has(normalizeField(alias)))
      })
      .map(([field]) => field)
    if (deadlocking.length > 0) {
      add(
        name,
        "deadlocked-contract",
        `arm requires ${deadlocking.map((f) => `\`${f}\``).join(", ")}, which the enforced ` +
          `inputSchema omits under additionalProperties:false — sending it is a 422, ` +
          `omitting it is a 400, so the command is unreachable by any payload (${arm.file})`
      )
    }
  }

  // A parameter is only "withheld" if someone wrote down why. Absence without
  // a reason stays a finding.
  const isHostChosen = (command, param) => Object.hasOwn(hostChosenParams, `${command}.${param}`)

  // --- 1. Truncated arguments: the headline check -------------------------
  for (const [name, arm] of arms) {
    const tauri = tauriCommands.get(name)
    if (!tauri || tauri.params.length === 0) continue
    if (isBridgeArm(arm.body) || consumesWholeArgs(arm.body)) continue
    const read = new Set([...armReadFields(arm.body)].map(normalizeField))
    const missing = tauri.params
      .filter((p) => !read.has(normalizeField(p.name)))
      .filter((p) => !isHostChosen(name, p.name))
    if (missing.length > 0) {
      add(
        name,
        "missing-params",
        `dispatch arm (${arm.file}) never reads ${missing.map((p) => `\`${p.name}\``).join(", ")} — ` +
          `declared by ${tauri.file}:${tauri.line}`
      )
    }
  }

  // --- 2. Contract schema narrower than the command -----------------------
  for (const [name, entry] of catalog) {
    const tauri = tauriCommands.get(name)
    if (!tauri || tauri.params.length === 0) continue
    const arm = arms.get(name)
    if (arm && (isBridgeArm(arm.body) || consumesWholeArgs(arm.body))) continue
    const declared = schemaProperties(entry.inputSchema)
    if (declared === null) continue // opaque input schema — reported separately
    const declaredSet = new Set(declared.map(normalizeField))
    const missing = tauri.params
      .filter((p) => !declaredSet.has(normalizeField(p.name)))
      .filter((p) => !isHostChosen(name, p.name))
    if (missing.length > 0) {
      add(
        name,
        "schema-missing-params",
        `contract inputSchema omits ${missing.map((p) => `\`${p.name}\``).join(", ")} — ` +
          `and the schema is ENFORCED at runtime, so sending them is a 422`
      )
    }
  }

  // --- 3. Allowlist ⟷ arm drift -------------------------------------------
  for (const [name, arm] of arms) {
    if (!knownCommands.has(name)) {
      add(
        name,
        "arm-not-allowlisted",
        `arm exists in ${arm.file} but is absent from KNOWN_COMMANDS — dead code`
      )
    }
  }
  for (const name of knownCommands) {
    // Browser RPCs are routed to the typed browser gateway at rpc.rs:2612,
    // before the submodule chain — the gateway IS their dispatch arm. Same
    // carve-out `every_known_command_has_a_dispatch_arm()` makes in Rust.
    if (browserCommands.has(name)) continue
    if (!arms.has(name)) {
      add(
        name,
        "known-command-without-arm",
        "allowlisted but no dispatch arm found — 404 on a real device"
      )
    }
  }

  // --- 3a. Published shape vs enforced shape, per plane -------------------
  // The public spec is what a device developer builds against; the catalog
  // (plus the device-plane overlay) is what `validate_contract_value` actually
  // enforces. When those two disagree the documented request is rejected 422 —
  // the exact shape of the git_* outage, where the spec published
  // `workspaceId`/`destinationRelativePath` and the enforced catalog demanded
  // `destination`. Nothing compared them, because the fork was deliberate.
  for (const [name, published] of publicSpecSchemas) {
    const enforced = devicePlaneOverrides.get(name) ?? catalog.get(name)?.inputSchema
    if (enforced === undefined || published === undefined) continue
    if (JSON.stringify(enforced) === JSON.stringify(published)) continue
    const publishedProps = new Set([...acceptedPropertyNames(published)].map(normalizeField))
    const enforcedProps = new Set([...acceptedPropertyNames(enforced)].map(normalizeField))
    if (enforcedProps.size === 0) continue // opaque or unmodelled — nothing to contradict
    const rejected = [...publishedProps].filter((p) => !enforcedProps.has(p))
    if (rejected.length > 0) {
      add(
        name,
        "published-shape-not-enforced",
        `the public spec documents ${rejected.length} propert(ies) the enforced device-plane ` +
          `schema does not accept — a client built from the docs gets 422`
      )
    }
  }

  // --- 3b. Exemptions must still name a real parameter --------------------
  // Otherwise the reasons rot: the command changes, the row survives, and the
  // next reader believes a justification that no longer describes anything.
  for (const key of Object.keys(hostChosenParams)) {
    const separator = key.lastIndexOf(".")
    const command = key.slice(0, separator)
    const param = key.slice(separator + 1)
    const tauri = tauriCommands.get(command)
    if (tauri === undefined) {
      add(command, "stale-host-chosen-exemption", `no such Tauri command — drop \`${key}\``)
      continue
    }
    if (!tauri.params.some((p) => normalizeField(p.name) === normalizeField(param))) {
      add(
        command,
        "stale-host-chosen-exemption",
        `\`${command}\` no longer declares \`${param}\` — drop \`${key}\``
      )
    }
  }

  // --- 4. Tauri commands nobody triaged -----------------------------------
  for (const name of registered) {
    if (manifestNames.has(name) || dispositionNames.has(name) || knownCommands.has(name)) continue
    add(
      name,
      "unregistered-command",
      "registered in generate_handler! but in neither companion-commands.json nor headless-command-dispositions.json"
    )
  }

  // --- 5. Report-only signals --------------------------------------------
  for (const [name, tauri] of tauriCommands) {
    if (tauri.channelParams.length === 0) continue
    if (!registered.has(name)) continue
    if (knownCommands.has(name)) continue
    if (streamReplacements[name]) continue
    add(
      name,
      "channel-command-excluded",
      `streams via Channel<T> (${tauri.channelParams.join(", ")}) and has no RPC path`
    )
  }
  // An exemption for a command that no longer streams — or no longer exists —
  // is a claim about something that is not there. Same rule as the
  // host-chosen-parameter table: the row has to keep earning its place.
  for (const name of Object.keys(streamReplacements)) {
    const tauri = tauriCommands.get(name)
    if (tauri === undefined) {
      if (tauriCommands.size === 0) continue // partial inventory (tests)
      add(name, "stale-stream-exemption", "exempted as a stream, but no such Tauri command exists")
    } else if (tauri.channelParams.length === 0) {
      add(
        name,
        "stale-stream-exemption",
        "exempted as a stream, but the command no longer takes a Channel<T> — it may now be plain-dispatchable"
      )
    } else if (knownCommands.has(name)) {
      add(
        name,
        "stale-stream-exemption",
        "exempted as having no RPC path, but it is in KNOWN_COMMANDS"
      )
    }
  }

  for (const [name, arm] of arms) {
    if (!requiresHeadless(arm.body)) continue
    if (serviceOnly.has(name)) continue
    if (headlessOwnedArms[name]) continue
    add(
      name,
      "desktop-dead",
      `device-reachable but requires headless services — answers 503 on a desktop-hosted ` +
        `companion server (${arm.file})`
    )
  }
  for (const name of Object.keys(headlessOwnedArms)) {
    const arm = arms.get(name)
    if (arm === undefined) {
      if (arms.size === 0) continue // partial inventory (tests)
      add(
        name,
        "stale-headless-owned-exemption",
        "exempted as headless-owned, but no such dispatch arm exists"
      )
    } else if (!requiresHeadless(arm.body)) {
      add(
        name,
        "stale-headless-owned-exemption",
        "exempted as headless-owned, but the arm no longer requires headless services"
      )
    }
  }
  // Response-schema debt, graded. Both kinds are report-only findings, but
  // they are ratcheted by count below — the list may only shrink.
  for (const [name, entry] of catalog) {
    const precision = responseSchemaPrecision(entry.outputSchema)
    if (precision === "any") {
      add(
        name,
        "opaque-response-schema",
        "outputSchema matches any JSON — response validation is a no-op"
      )
    } else if (precision === "container") {
      add(
        name,
        "unconstrained-response-contents",
        "outputSchema pins the root type but nothing inside it — a wrong root " +
          "is rejected, a wrong payload is not"
      )
    }
  }

  // --- 9. "covered-by-headless" must name the cover -------------------------
  // This disposition asserts that the operator can already do the thing some
  // other way, and it was carrying 74 commands on one shared sentence. Three
  // families in it were not covered by anything: `subscription_*` is documented
  // in the source as deliberately desktop-only (the opposite claim), `scheduler_*`
  // needs a `SchedulerState` only the desktop builder manages, and the native
  // half of `vector_*` operates on an on-disk store no headless process owns.
  //
  // A claim of coverage that cannot name what covers it is indistinguishable
  // from an unexamined command, so it has to name it.
  for (const group of dispositionGroups) {
    if (group.disposition !== "covered-by-headless") continue
    for (const name of group.commands ?? []) {
      if (group.commandReasons?.[name]) continue
      add(
        name,
        "unsubstantiated-coverage-claim",
        `filed covered-by-headless with only the shared group reason — name the covering ` +
          `command, route, or configuration in commandReasons, or file it elsewhere`
      )
    }
  }

  // --- 10. Event-channel catalog vs. reality -------------------------------
  // The event axis had no gate of any kind: `spec_parity.rs` never mentioned
  // "event", `CommandDescriptor` had no streaming field, and `app.emit` could
  // be added anywhere without failing a test. These two checks are the first
  // mechanical link between "a channel is declared deliverable" and "a channel
  // exists".
  //
  // Both are report-only. A catalogued-but-unemitted entry is sometimes
  // deliberate forward wiring (`browser://snapshot`), and the emitted-but-
  // uncatalogued set is dominated by host-local UI plumbing that is *correctly*
  // undeliverable. Gating either would punish the right answer.
  for (const [pattern, spec] of eventCatalog) {
    if (pattern.endsWith("*")) continue // families cannot be matched literally
    if (channelReferences.exact?.has(pattern)) continue
    if (channelReferences.prefixes?.some((head) => pattern.startsWith(head))) continue
    add(
      pattern,
      "unreferenced-catalog-entry",
      `declared remotely deliverable${spec.defaultOn ? " and on by default" : ""} but the ` +
        `name appears nowhere outside the catalog — the constant behind it was likely ` +
        `renamed, leaving an entry that can never match a frame`
    )
  }
  for (const [channel, site] of emittedChannels) {
    if (matchesEventCatalog(eventCatalog, channel)) continue
    if (HOST_LOCAL_CHANNELS.some((prefix) => channel.startsWith(prefix))) continue
    add(
      channel,
      "uncatalogued-event-channel",
      `emitted at ${site} but absent from EVENT_CHANNELS — a remote client subscribing ` +
        `to it is refused, so any command whose result rides it is a silent no-op`
    )
  }

  return findings.sort((a, b) => a.key.localeCompare(b.key))
}

// ---------------------------------------------------------------------------
// I/O + baseline
// ---------------------------------------------------------------------------

/** @returns {string[]} tracked Rust files that may define a command */
function listRustFiles() {
  return execFileSync("git", ["ls-files", "*.rs"], {
    cwd: REPO_ROOT,
    encoding: "utf8",
    maxBuffer: 64e6,
  })
    .split("\n")
    .filter(Boolean)
    .filter((f) => COMMAND_ROOTS.some((root) => f.startsWith(root)))
    .filter((f) => existsSync(join(REPO_ROOT, f)))
}

const read = (p) => readFileSync(join(REPO_ROOT, p), "utf8")
const readJson = (p) => JSON.parse(read(p))

/**
 * Dispatch sources whose arms do NOT live under `companion_api/rpc/`.
 *
 * `rpc/sftp.rs` is a one-line hand-off to `sftp_service::dispatch_sftp`, and
 * that function is where the arms actually are, because the desktop's own
 * `#[tauri::command]` wrappers share it — so it is named for what it does
 * rather than for the RPC table it happens to serve.
 * `gen-companion-api.mjs:RPC_DISPATCH_SOURCE_PATHS` lists the same file.
 */
export const DELEGATED_ARM_FILES = ["src-tauri/src/sftp_service.rs"]

/**
 * The files to scan for dispatch arms: every tracked `companion_api/rpc/*.rs`
 * that is not a test module, plus {@link DELEGATED_ARM_FILES}, minus anything
 * that is not actually on disk.
 *
 * Both subtractions are load-bearing, and neither is a tidy-up:
 *
 *   - Dropping a delegated file does not merely under-report. It MIS-reports:
 *     all 14 SFTP commands parse as arm-less and the gate names 14 runtime
 *     404s that do not exist, which is how the 18 real findings in the same
 *     run got buried.
 *   - `git ls-files` still lists a tracked file that has been deleted but not
 *     staged. Reading one throws ENOENT out of the middle of the scan, so the
 *     gate crashes instead of returning a verdict — and a crash says nothing
 *     about the files that DO exist. The existence filter therefore belongs to
 *     the selection, not to a caller who might forget it.
 *
 * Pure apart from the injectable `exists` probe, so both rules are testable
 * without a working tree in a particular state.
 *
 * @param {string[]} trackedRpcFiles raw `git ls-files` lines
 * @param {{ delegated?: string[], exists?: (file: string) => boolean }} [options]
 * @returns {string[]}
 */
export function selectArmFiles(trackedRpcFiles, options = {}) {
  const delegated = options.delegated ?? DELEGATED_ARM_FILES
  const exists = options.exists ?? ((file) => existsSync(join(REPO_ROOT, file)))
  const selected = []
  for (const file of [...trackedRpcFiles, ...delegated]) {
    if (!file || file.endsWith("tests.rs")) continue
    if (selected.includes(file)) continue
    if (!exists(file)) continue
    selected.push(file)
  }
  return selected
}

/** Gather every input the analysis needs from disk. */
export function collectInputs() {
  const emitSources = listEmitSourceFiles()
  const tauriCommands = new Map()
  for (const file of listRustFiles()) {
    for (const command of parseTauriCommands(read(file), file)) {
      // Duplicate names exist across crates (two `terminal_spawn`s); the one
      // that matters is whichever `generate_handler!` registers, and both
      // shapes are equivalent for our purposes. First wins, deterministically.
      if (!tauriCommands.has(command.name)) tauriCommands.set(command.name, command)
    }
  }

  const rpcSource = read("src-tauri/src/companion_api/rpc.rs")
  const arms = new Map()
  const armFiles = selectArmFiles(
    execFileSync("git", ["ls-files", "src-tauri/src/companion_api/rpc/*.rs"], {
      cwd: REPO_ROOT,
      encoding: "utf8",
    }).split("\n")
  )
  for (const file of armFiles) {
    for (const arm of extractDispatchArms(read(file), file)) {
      for (const name of arm.names) {
        if (!arms.has(name)) arms.set(name, { body: arm.body, file: arm.file })
      }
    }
  }

  const catalogRaw = readJson("crates/cognia-cli/assets/host-command-catalog.json")
  const catalogEntries = Array.isArray(catalogRaw.commands)
    ? catalogRaw.commands
    : Object.entries(catalogRaw.commands ?? {}).map(([name, v]) => ({ name, ...v }))
  const catalog = new Map(catalogEntries.map((c) => [c.name, c]))

  const manifest = readJson("protocol/companion-commands.json")
  const dispositionLedger = readJson("protocol/headless-command-dispositions.json")
  const dispositionNames = parseDispositionNames(dispositionLedger)

  return {
    tauriCommands,
    registered: parseRegisteredCommands(read("src-tauri/src/lib.rs")),
    knownCommands: extractRustStringArray(rpcSource, "KNOWN_COMMANDS"),
    serviceOnly: extractRustStringArray(rpcSource, "SERVICE_ONLY_COMMANDS"),
    arms,
    catalog,
    manifestNames: new Set((manifest.commands ?? []).map((c) => c.name)),
    dispositionNames,
    dispositionGroups: dispositionLedger.groups ?? [],
    browserCommands: extractRustStringArray(
      read("src-tauri/src/companion_api/browser_gateway.rs"),
      "BROWSER_RPC_COMMANDS"
    ),
    publicSpecSchemas: parsePublicSpecRequestSchemas(
      read("docs/api/mobile-companion-api.openapi.yaml")
    ),
    devicePlaneOverrides: parseDevicePlaneOverrides(
      readJson("crates/cognia-headless-contract/assets/device-plane-overrides.json")
    ),
    eventCatalog: parseEventChannelCatalog(read("src-tauri/src/companion_api/event_channels.rs")),
    emittedChannels: collectEmittedChannels(emitSources),
    channelReferences: collectChannelReferences(emitSources),
  }
}

/**
 * Sources that may emit an event channel: the Rust command surface plus the
 * renderer, since a good half of these channels are emitted from TypeScript
 * (`claude://message-added`, every `workflow://*`, `sync://invalidate`).
 *
 * Test files are excluded — a fixture channel is not a production stream, and
 * counting them would make the dead-entry check permanently green.
 *
 * @returns {Array<{file: string, source: string}>}
 */
function listEmitSourceFiles() {
  const files = execFileSync("git", ["ls-files", "*.rs", "*.ts", "*.tsx"], {
    cwd: REPO_ROOT,
    encoding: "utf8",
    maxBuffer: 64e6,
  })
    .split("\n")
    .filter(Boolean)
    .filter(
      (f) =>
        COMMAND_ROOTS.some((root) => f.startsWith(root)) ||
        EMIT_SOURCE_ROOTS.some((root) => f.startsWith(root))
    )
    .filter((f) => !/\.(test|spec|stories)\.[cm]?tsx?$/.test(f))
    .filter((f) => existsSync(join(REPO_ROOT, f)))
  return files.map((file) => ({ file, source: read(file) }))
}

/**
 * `/api/_rpc/<name>` request schemas from the published mobile spec.
 *
 * Parsed with a targeted scan rather than a YAML dependency: this gate must
 * not acquire the generator's toolchain to answer one question. Blocks are
 * delimited by the next path key at the same indentation.
 *
 * @param {string} yaml
 * @returns {Map<string, unknown>}
 */
export function parsePublicSpecRequestSchemas(yaml) {
  const out = new Map()
  const lines = yaml.split(/\r?\n/)
  for (let i = 0; i < lines.length; i += 1) {
    const header = lines[i].match(/^ {2}\/api\/_rpc\/([a-z][a-z0-9_]*):\s*$/)
    if (!header) continue
    let end = i + 1
    while (end < lines.length && !/^ {2}\S/.test(lines[end])) end += 1
    // Scope to requestBody. A no-arg command has no request properties at all,
    // and the first `properties:` in its path block belongs to the response
    // error envelope — whose three keys (code/message/retryable) otherwise get
    // reported as request fields the runtime rejects.
    const block = lines.slice(i, end)
    const bodyStart = block.findIndex((line) => /^\s*requestBody:\s*$/.test(line))
    if (bodyStart < 0) continue
    const responsesAt = block.findIndex(
      (line, index) => index > bodyStart && /^\s*responses:\s*$/.test(line)
    )
    const bodyEnd = responsesAt < 0 ? block.length : responsesAt
    const schema = extractYamlSchemaBlock(block.slice(bodyStart, bodyEnd).join("\n"))
    if (schema) out.set(header[1], schema)
  }
  return out
}

/**
 * The `schema:` mapping under a path's requestBody, as property names only.
 * A full YAML parse is unnecessary: the comparison this feeds is on property
 * SETS, so the block's `propertyName:` keys are the whole signal.
 *
 * @param {string} block
 * @returns {{ properties: Record<string, object> } | null}
 */
export function extractYamlSchemaBlock(block) {
  const lines = block.split(/\r?\n/)
  // Work on whole lines: slicing at the marker would drop the `properties:`
  // line's own indentation, making every child look mis-indented and the
  // whole check a silent no-op.
  const start = lines.findIndex((line) => /^\s*properties:\s*$/.test(line))
  if (start < 0) return null
  const indent = (lines[start].match(/^\s*/) ?? [""])[0].length
  const properties = {}
  for (const line of lines.slice(start + 1)) {
    if (line.trim() === "") continue
    const own = (line.match(/^\s*/) ?? [""])[0].length
    if (own <= indent) break
    const key = line.match(/^\s+([A-Za-z_][A-Za-z0-9_]*):/)
    if (key && own === indent + 2) properties[key[1]] = {}
  }
  return Object.keys(properties).length > 0 ? { properties } : null
}

/**
 * Device-plane input schemas, keyed by command.
 * @param {{ commands?: Record<string, { inputSchema?: unknown }> }} overrides
 * @returns {Map<string, unknown>}
 */
export function parseDevicePlaneOverrides(overrides) {
  return new Map(
    Object.entries(overrides?.commands ?? {}).map(([name, entry]) => [name, entry.inputSchema])
  )
}

/** @returns {{ version: number, findings: string[] }} */
export function readBaseline(file = BASELINE_FILE) {
  if (!existsSync(file)) return { version: 1, findings: [] }
  return JSON.parse(readFileSync(file, "utf8"))
}

/**
 * Report-only kinds held to a shrinking COUNT rather than a key list.
 *
 * Response-schema debt is paid down per command, in batches, over many
 * changes — a key list would churn on every batch and reviewers would stop
 * reading it. A ceiling answers the only question that matters between
 * batches: did this change type more responses than it un-typed?
 */
export const RATCHETED_KINDS = ["opaque-response-schema", "unconstrained-response-contents"]

/**
 * Current count for each ratcheted kind. Pure.
 * @param {Array<{kind: string}>} findings
 * @returns {Record<string, number>}
 */
export function countRatchetedKinds(findings) {
  const counts = Object.fromEntries(RATCHETED_KINDS.map((k) => [k, 0]))
  for (const f of findings) if (f.kind in counts) counts[f.kind] += 1
  return counts
}

/**
 * Kinds whose count rose above the recorded ceiling. Pure.
 * @param {Record<string, number>} current
 * @param {Record<string, number>} ceilings
 * @returns {Array<{kind: string, current: number, ceiling: number}>}
 */
export function ceilingRegressions(current, ceilings) {
  return RATCHETED_KINDS.filter((kind) => kind in ceilings)
    .map((kind) => ({ kind, current: current[kind] ?? 0, ceiling: ceilings[kind] }))
    .filter((row) => row.current > row.ceiling)
}

export function writeBaseline(allFindings, file = BASELINE_FILE) {
  const payload = {
    version: 2,
    note:
      "Known RPC↔Tauri semantic gaps, recorded when the gate landed. This list may " +
      "only shrink: `pnpm audit:rpc-semantic-parity` fails when a new one appears. " +
      "Each key is `<command>:<kind>`. Regenerate with " +
      "`pnpm audit:rpc-semantic-parity -- --write-baseline` after paying debt down.",
    ceilingNote:
      "Response-schema debt is ratcheted by count, not by key, because it is paid " +
      "down per command in batches. A count above its ceiling fails the gate; a " +
      "count below it prints the gain and asks you to lock it in. Output validation " +
      "is enforced at remote_execution.rs:293 and :362, so a schema tightened past " +
      "what the dispatch arm actually returns turns a working command into an error " +
      "response — type each one from the arm's return expression, not from the " +
      "#[tauri::command] signature.",
    findings: [
      ...new Set(allFindings.filter((f) => GATED_KINDS.has(f.kind)).map((f) => f.key)),
    ].sort(),
    ceilings: countRatchetedKinds(allFindings),
  }
  writeFileSync(file, `${JSON.stringify(payload, null, 2)}\n`)
  return payload
}

/**
 * Ratchet comparison. Pure.
 * @param {Array<{key: string}>} current
 * @param {string[]} baseline
 * @returns {{ added: string[], fixed: string[] }}
 */
export function diffAgainstBaseline(current, baseline) {
  const baseSet = new Set(baseline)
  const curSet = new Set(current.map((f) => f.key))
  return {
    added: current
      .filter((f) => !baseSet.has(f.key))
      .map((f) => f.key)
      .sort(),
    fixed: baseline.filter((k) => !curSet.has(k)).sort(),
  }
}

export function main(argv = []) {
  const inputs = collectInputs()
  const allFindings = analyze(inputs)
  const gated = allFindings.filter((f) => GATED_KINDS.has(f.kind))

  if (argv.includes("--report")) {
    const byKind = new Map()
    for (const f of allFindings) {
      if (!byKind.has(f.kind)) byKind.set(f.kind, [])
      byKind.get(f.kind).push(f)
    }
    console.log(
      `[rpc-semantic-parity] ${inputs.tauriCommands.size} Tauri commands, ` +
        `${inputs.registered.size} registered, ${inputs.knownCommands.size} RPC-reachable, ` +
        `${inputs.arms.size} dispatch arms.\n`
    )
    for (const [kind, items] of [...byKind].sort((a, b) => b[1].length - a[1].length)) {
      console.log(`\n### ${kind} (${items.length})`)
      for (const f of items) console.log(`  ${f.command}: ${f.detail}`)
    }
    return 0
  }

  if (argv.includes("--write-baseline")) {
    const payload = writeBaseline(allFindings)
    console.log(
      `[rpc-semantic-parity] baseline written: ${payload.findings.length} known finding(s), ` +
        `ceilings ${JSON.stringify(payload.ceilings)}`
    )
    return 0
  }

  const baseline = readBaseline()
  const { added, fixed } = diffAgainstBaseline(gated, baseline.findings ?? [])

  const counts = countRatchetedKinds(allFindings)
  const regressed = ceilingRegressions(counts, baseline.ceilings ?? {})
  const improved = RATCHETED_KINDS.filter(
    (kind) => kind in (baseline.ceilings ?? {}) && counts[kind] < baseline.ceilings[kind]
  )

  if (regressed.length) {
    console.error("[rpc-semantic-parity] response-schema debt went UP:")
    for (const { kind, current, ceiling } of regressed) {
      console.error(`  ${kind}: ${current} (ceiling ${ceiling})`)
    }
    console.error(
      "\n  A new command shipped without a real outputSchema, or a typed schema was\n" +
        "  widened back to a Legacy* $def. Type it from the dispatch arm's return\n" +
        "  expression in protocol/companion-response-schemas.json, then regenerate\n" +
        "  with `node scripts/build/gen-companion-api.mjs`."
    )
    return 1
  }

  if (improved.length) {
    console.log(
      `[rpc-semantic-parity] response-schema debt paid down (${improved
        .map((k) => `${k}: ${baseline.ceilings[k]} → ${counts[k]}`)
        .join(", ")}) — run \`pnpm audit:rpc-semantic-parity -- --write-baseline\` ` +
        "to lock the gain in."
    )
  }

  if (fixed.length) {
    console.log(
      `[rpc-semantic-parity] ${fixed.length} baselined finding(s) are resolved — ` +
        "run `pnpm audit:rpc-semantic-parity -- --write-baseline` to lock the gain in."
    )
  }

  if (added.length) {
    const byKey = new Map(allFindings.map((f) => [f.key, f]))
    console.error(`[rpc-semantic-parity] ${added.length} new semantic gap(s):`)
    for (const key of added) console.error(`  ${key}\n      ${byKey.get(key)?.detail ?? ""}`)
    console.error(
      "\n  A command is not 'covered' because its name is in KNOWN_COMMANDS. If the\n" +
        "  dispatch arm drops an argument, remote callers cannot reach that behaviour\n" +
        "  at all — and because the contract schema is enforced at runtime, sending\n" +
        "  the fuller payload fails 422 instead of degrading. Fix the arm AND the\n" +
        "  hand-written schema together, or record a written reason.\n" +
        "  Report every finding, including ungated ones: -- --report"
    )
    return 1
  }

  console.log(
    `[rpc-semantic-parity] OK: ${gated.length} known gated finding(s), none new ` +
      `(baseline holds ${(baseline.findings ?? []).length}); ` +
      `${allFindings.length - gated.length} report-only signal(s); ` +
      `response-schema debt ${RATCHETED_KINDS.map((k) => `${k}=${counts[k]}`).join(" ")}.`
  )
  return 0
}

if (
  import.meta.url === `file://${process.argv[1]}` ||
  process.argv[1]?.endsWith("check-rpc-semantic-parity.mjs")
) {
  process.exit(main(process.argv.slice(2)))
}
